import React, { useState, useCallback } from "react";
import { TbMapPinHeart } from "react-icons/tb";
import { GoLinkExternal } from "react-icons/go";
import { GoChevronUp, GoChevronDown } from "react-icons/go";
import { Badge } from "flowbite-react";
import YouTube from "react-youtube";
import LazyComponent from "../../modules/LazyComponent";
import UtilityService from "../../../services/UtilityService";
import { Place, PlaceItem } from "../../../types/places";

interface PlaceSectionProps {
  places: Place[];
}

interface LatLngLiteral {
  lat: number;
  lng: number;
}

interface MarkerInfo extends Place, PlaceItem {
  position: LatLngLiteral;
  visible: boolean;
}

const PlaceSection: React.FC<PlaceSectionProps> = ({ places }) => {
  const [expandedPlaceIds, setExpandedPlaceIds] = useState<Set<number>>(
    new Set()
  );

  const calculateCenter = useCallback(
    (items: PlaceItem[] | LatLngLiteral[]): LatLngLiteral => {
      let center: LatLngLiteral = {
        lat: 0,
        lng: 0,
      };
      if (items.length === 1) {
        center = {
          lat: items[0].lat,
          lng: items[0].lng,
        };
      } else if (items.length > 1) {
        center = items.reduce((previous, current) => {
          previous.lat += current.lat;
          previous.lng += current.lng;
          return previous;
        }, center);
        center.lat = center.lat / items.length;
        center.lng = center.lng / items.length;
      }
      return center;
    },
    []
  );

  const initialLatLngList = places
    .map((place) =>
      (place.items ?? []).map((item) => ({
        ...place,
        ...item,
        position: { lat: item.lat, lng: item.lng },
        visible: true,
      }))
    )
    .flat();

  const [state, setState] = useState({
    latLngList: initialLatLngList,
    center: calculateCenter(initialLatLngList),
    zoom: 5,
  });

  const toggleExpand = (placeId: number) => {
    setExpandedPlaceIds((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(placeId)) {
        newSet.delete(placeId);
      } else {
        newSet.add(placeId);
      }
      return newSet;
    });
  };

  const handlePlaceClick = useCallback(
    (place: Place) => {
      if (place.items) {
        const center = calculateCenter(place.items);
        setState((prevState) => ({
          ...prevState,
          latLngList: prevState.latLngList.map((listItem) => ({
            ...listItem,
            visible: listItem.placeId === place.placeId,
          })),
          center,
          zoom: place.zoom,
        }));
      }
    },
    [calculateCenter]
  );

  const getBadgeColor = (type: string) => {
    if (type === "MV") return "warning";
    if (type === "CM") return "purple";
    if (type === "TV") return "pink";
    return "gray";
  };

  return (
    <section id="PLACE" style={{ contentVisibility: "auto" }}>
      <div className="pt-6 pb-2 px-2 sm:pt-12">
        <h2 className="flex items-center font-bold text-lg text-shadow">
          <TbMapPinHeart className="text-lg mr-2" />
          <span className="underline underline-offset-4 decoration-dashed decoration-1">
            PLACE(聖地)
          </span>
        </h2>
        <div className="pt-2 text-xs sm:text-base break-words leading-relaxed tracking-widest">
          PLACEではReolが過去にMV撮影やTV番組の収録等で訪れたことのあるいわゆる「聖地」の情報を掲載しております。
          <br />
          聖地巡礼の参考情報としてご覧ください（掲載されていない情報があればぜひ教えていただけますと幸いです）。
        </div>
      </div>
      <div className="space-y-8 px-2">
        <div className="space-y-2">
          {places.map((place) => {
            const isExpanded = expandedPlaceIds.has(place.placeId);
            return (
              <div key={`place-${place.placeId}`} className="mb-2">
                <div
                  onClick={() => {
                    toggleExpand(place.placeId);
                    if (!isExpanded) {
                      handlePlaceClick(place);
                    }
                  }}
                  className="relative cursor-pointer rounded-lg transition-all duration-300 overflow-hidden text-black"
                  style={{
                    width: isExpanded ? "calc(100% + 0.5rem)" : "100%",
                    marginLeft: isExpanded ? "-0.25rem" : "0",
                    background: "linear-gradient(135deg, #ffffff, #d1d5db)",
                    boxShadow: isExpanded
                      ? "0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)"
                      : "0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06)",
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.boxShadow =
                      "0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)";
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.boxShadow = isExpanded
                      ? "0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)"
                      : "0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06)";
                  }}
                >
                  {/* 非展開時: コンパクト表示 */}
                  {!isExpanded && (
                    <div className="p-4">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2 flex-1 min-w-0">
                          {place.type && (
                            <Badge
                              color={getBadgeColor(place.type)}
                              className="flex-shrink-0"
                            >
                              {place.type}
                            </Badge>
                          )}
                          <span className="text-sm font-medium tracking-wide truncate">
                            {place.title}
                          </span>
                        </div>
                        <GoChevronDown className="flex-shrink-0 ml-2" />
                      </div>
                    </div>
                  )}

                  {/* 展開時: 詳細表示 */}
                  {isExpanded && (
                    <div className="p-4">
                      {/* ヘッダー */}
                      <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center gap-2 flex-1 min-w-0">
                          {place.type && (
                            <Badge
                              color={getBadgeColor(place.type)}
                              className="flex-shrink-0"
                            >
                              {place.type}
                            </Badge>
                          )}
                          <span className="text-base font-bold tracking-wide">
                            {place.title}
                          </span>
                        </div>
                        <GoChevronUp className="flex-shrink-0 ml-2" />
                      </div>

                      {/* YouTube動画 */}
                      {place.url && place.url.indexOf("youtu.be") !== -1 && (
                        <div className="mb-4" onClick={(e) => e.stopPropagation()}>
                          <LazyComponent>
                            <div className="relative w-full" style={{ paddingBottom: "56.25%" }}>
                              <YouTube
                                videoId={place.url.replace("https://youtu.be/", "")}
                                opts={{
                                  playerVars: {
                                    autoplay: 0,
                                    enablejsapi: 1,
                                    playsinline: 1,
                                    loop: 1,
                                    rel: 0,
                                    color: "white",
                                  },
                                }}
                                className="absolute top-0 left-0 w-full h-full"
                                iframeClassName="w-full h-full rounded"
                              />
                            </div>
                          </LazyComponent>
                        </div>
                      )}

                      {/* 場所アイテム */}
                      {place.items?.map((item) => (
                        <div
                          key={`place-${item.placeId}-${item.placeItemId}`}
                          className="mb-6 last:mb-0 bg-gray-50 rounded-lg p-4"
                          onClick={(e) => e.stopPropagation()}
                        >
                          {item.placeUrl ? (
                            <a
                              href={item.placeUrl}
                              className="block mb-2"
                              target="_blank"
                              rel="noopener noreferrer"
                            >
                              <h3 className="flex items-center text-sm font-bold tracking-wide hover:underline">
                                {item.placeItemId}.&nbsp;{item.name}
                                <GoLinkExternal className="ml-1 text-xs" />
                              </h3>
                            </a>
                          ) : (
                            <h3 className="text-sm font-bold tracking-wide mb-2">
                              {item.placeItemId}.&nbsp;{item.name}
                            </h3>
                          )}
                          {item.memo && (
                            <p
                              className="text-sm mb-2"
                              dangerouslySetInnerHTML={{
                                __html: UtilityService.sanitizeHTML(item.memo),
                              }}
                            />
                          )}
                          <iframe
                            src={item.mapsEmbedUrl}
                            className="w-full h-48 rounded mb-2"
                            loading="lazy"
                            referrerPolicy="no-referrer-when-downgrade"
                            title={`Map for ${item.name}`}
                          />
                          <p className="text-xs text-gray-600">{item.address}</p>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
        <p className="text-xs py-2">
          ※ここに載っていない聖地情報いつでもお待ちしております
        </p>
      </div>
    </section>
  );
};

export default PlaceSection;
